//! `jsrt::JsBigInt` against `fixtures/bigint.json`, generated by Node 26.

mod common;

use std::cmp::Ordering;

use common::*;
use jsrt::JsBigInt;
use jsrt::number::parse_bigint;
use serde_json::Value;

fn big(v: &Value) -> JsBigInt {
    let s = v
        .as_str()
        .unwrap_or_else(|| panic!("expected a bigint string, got {v}"));
    parse_bigint(s).unwrap_or_else(|| panic!("bad bigint {s}"))
}

fn f64_of(v: &Value) -> f64 {
    f64::from_bits(u64::from_str_radix(v.as_str().expect("bits"), 16).expect("hex bits"))
}

/// `None` where node threw, else the decimal string.
fn result(v: &Value) -> Option<String> {
    v.as_str().map(str::to_owned)
}

fn show(r: Option<JsBigInt>) -> Option<String> {
    r.map(|b| b.to_js_string())
}

fn bigints() -> Value {
    fixture("bigint.json")
}

#[test]
fn operations() {
    let f = bigints();
    for case in arr(&f["ops"]) {
        let (a, b) = (big(&case["a"]), big(&case["b"]));
        let small = big(&case["small"]);
        let shift = big(&case["shift"]);
        let ctx = format!("a={a:?} b={b:?}");
        assert_eq!(show(a.checked_add(&b)), result(&case["add"]), "add {ctx}");
        assert_eq!(show(a.checked_sub(&b)), result(&case["sub"]), "sub {ctx}");
        assert_eq!(show(a.checked_mul(&b)), result(&case["mul"]), "mul {ctx}");
        assert_eq!(show(a.checked_div(&b)), result(&case["div"]), "div {ctx}");
        assert_eq!(show(a.checked_rem(&b)), result(&case["rem"]), "rem {ctx}");
        assert_eq!(
            show(a.checked_pow(&small)),
            result(&case["pow"]),
            "pow {ctx} {small:?}"
        );
        assert_eq!(
            show(a.checked_pow(&-&small)),
            result(&case["negPow"]),
            "pow {ctx} -{small:?}"
        );
        assert_eq!(
            show(a.checked_shl(&shift)),
            result(&case["shl"]),
            "shl {ctx} {shift:?}"
        );
        assert_eq!(
            show(a.checked_shr(&shift)),
            result(&case["shr"]),
            "shr {ctx} {shift:?}"
        );
        assert_eq!(
            (&a & &b).to_js_string(),
            case["and"].as_str().unwrap(),
            "and {ctx}"
        );
        assert_eq!(
            (&a | &b).to_js_string(),
            case["or"].as_str().unwrap(),
            "or {ctx}"
        );
        assert_eq!(
            (&a ^ &b).to_js_string(),
            case["xor"].as_str().unwrap(),
            "xor {ctx}"
        );
        assert_eq!(
            (!&a).to_js_string(),
            case["not"].as_str().unwrap(),
            "not {ctx}"
        );
        assert_eq!(
            (-&a).to_js_string(),
            case["neg"].as_str().unwrap(),
            "neg {ctx}"
        );
        assert_eq!(a.cmp(&b), int(&case["cmp"]).cmp(&0), "cmp {ctx}");
        let n = f64_of(&case["number"]);
        assert_eq!(a.to_f64().to_bits(), n.to_bits(), "Number({ctx})");
        let radix = u32::try_from(int(&case["radix"])).unwrap();
        assert_eq!(
            a.to_string_radix(radix),
            case["str"].as_str().unwrap(),
            "toString({radix}) {ctx}"
        );
    }
}

#[test]
fn compare_with_number() {
    let f = bigints();
    for case in arr(&f["mixed"]) {
        let a = big(&case[0]);
        let x = f64_of(&case[1]);
        let want: Vec<bool> = arr(case)[2..]
            .iter()
            .map(|v| v.as_bool().unwrap())
            .collect();
        let got = vec![a < x, a > x, a == x, a <= x, a >= x];
        assert_eq!(got, want, "{a:?} vs {x:?}");
        let got_rev = vec![x > a, x < a, x == a, x >= a, x <= a];
        assert_eq!(got_rev, want, "{x:?} vs {a:?}");
    }
}

#[test]
fn from_number() {
    let f = bigints();
    for case in arr(&f["fromNumber"]) {
        let x = f64_of(&case[0]);
        assert_eq!(
            show(JsBigInt::from_f64(x)),
            result(&case[1]),
            "BigInt({x:?})"
        );
    }
}

#[test]
fn parse() {
    let f = bigints();
    for case in arr(&f["parse"]) {
        let s = case[0].as_str().unwrap();
        assert_eq!(show(parse_bigint(s)), result(&case[1]), "BigInt({s:?})");
    }
}

fn limit_case(name: &str) -> Option<JsBigInt> {
    let k = JsBigInt::from(1i64 << 30);
    let kk = JsBigInt::from(1i64 << 60);
    let n = JsBigInt::from;
    let big = || {
        n(1).checked_shl(&n((1 << 30) - 1))
            .unwrap()
            .checked_sub(&n(1))
            .unwrap()
    };
    let half = || n(1).checked_shl(&n(1 << 29)).unwrap();
    let half_minus = || n(1).checked_shl(&n((1 << 29) - 1)).unwrap();
    match name {
        "pow_2_k_minus_1" => n(2).checked_pow(&n((1 << 30) - 1)),
        "pow_2_k" => n(2).checked_pow(&k),
        "pow_minus_2_k_minus_1" => n(-2).checked_pow(&n((1 << 30) - 1)),
        "pow_minus_1_huge" => n(-1).checked_pow(&kk),
        "pow_1_huge" => n(1).checked_pow(&kk),
        "pow_0_huge" => n(0).checked_pow(&kk),
        "pow_3_k" => n(3).checked_pow(&k),
        "pow_2_huge" => n(2).checked_pow(&kk),
        "shl_1_k_minus_1" => n(1).checked_shl(&n((1 << 30) - 1)),
        "shl_1_k" => n(1).checked_shl(&k),
        "shl_1_k_plus_1" => n(1).checked_shl(&n((1 << 30) + 1)),
        "shl_3_k_minus_2" => n(3).checked_shl(&n((1 << 30) - 2)),
        "shl_3_k_minus_1" => n(3).checked_shl(&n((1 << 30) - 1)),
        "shl_0_huge" => n(0).checked_shl(&kk),
        "shl_minus_1_by_minus_huge" => n(-1).checked_shl(&-&kk),
        "shr_5_by_minus_k" => n(5).checked_shr(&-&k),
        "add_big_big" => big().checked_add(&big()),
        "sub_big_minus_big" => big().checked_sub(&-big()),
        "sub_big_big" => big().checked_sub(&big()),
        "mul_half_half" => half().checked_mul(&half_minus()),
        _ => panic!("unknown limit case {name}"),
    }
}

#[test]
fn size_limit() {
    let f = bigints();
    for case in arr(&f["limits"]) {
        let name = case[0].as_str().unwrap();
        let got = limit_case(name).map(|b| (b.as_bigint().bits(), b.is_negative()));
        let want = case[1]
            .as_u64()
            .map(|bits| (bits, case[2].as_bool().unwrap()));
        assert_eq!(got, want, "{name}");
    }
}

#[test]
fn compare_orders() {
    assert_eq!(JsBigInt::from(1).partial_cmp(&f64::NAN), None);
    assert_eq!(JsBigInt::from(1).partial_cmp(&1.5), Some(Ordering::Less));
}
